properties.query:
let dt_lookBack = 1h;
let ioc_lookBack = 14d;
let domain_indicators =  (union isfuzzy=true
(ThreatIntelligenceIndicator
| where SourceSystem contains "Anomali_ASI"
| where TimeGenerated > ago(ioc_lookBack) and ExpirationDateTime > now()
//| summarize LatestIndicatorTime = arg_max(TimeGenerated, *) by IndicatorId
| where Active == true
| parse Description with * "iType:" iType ";" *
| where iType has_any ("suspicious_domain", "mal_domain", "c2_domain", "apt_domain")
| extend Org = iif(isnotempty(split(Description, ";", 4)), split(Description, ";", 3), "No Org")
| extend Source = iff((Org == "No Org"), split(Description, ";", 3), split(Description, ";", 4))
| extend TI_Domain = DomainName 
)
);
domain_indicators
  | join kind=innerunique (Syslog
    | where TimeGenerated > ago(dt_lookBack)
    // Filter on Watchguard Firebox logs
    | where SyslogMessage contains "firebox"
    // Extract domain patterns from syslog message
    | extend WG_domain = extract("(([a-z0-9]+(-[a-z0-9]+)*\\.)+[a-z]{2,})",1, tolower(SyslogMessage))
    | where isnotempty(WG_domain)
    | extend Syslog_TimeGenerated = TimeGenerated
  ) on $left.TI_Domain == $right.WG_domain
| where Syslog_TimeGenerated < ExpirationDateTime
| summarize LatestIndicatorTime = arg_max(TimeGenerated, *) by IndicatorId
| project TI_Domain, Org, Tags, Source, LatestIndicatorTime, Description, iType, IndicatorId, ExpirationDateTime, Syslog_TimeGenerated, WG_domain, HostIP, SyslogMessage, Computer
